DROP TABLE IF EXISTS expensive_books;

CREATE TABLE expensive_books AS
SELECT *
FROM books
WHERE rental_price > 7.00;

SELECT * FROM expensive_books;

DELIMITER //

CREATE PROCEDURE update_book_status(
    IN p_book_isbn VARCHAR(50),
    IN p_action VARCHAR(10)
)
BEGIN
    IF p_action = 'issue' THEN
        UPDATE books
        SET status = 'no'
        WHERE isbn = p_book_isbn;

    ELSEIF p_action = 'return' THEN
        UPDATE books
        SET status = 'yes'
        WHERE isbn = p_book_isbn;

    ELSE
        SIGNAL SQLSTATE '45000'
        SET MESSAGE_TEXT = 'Invalid action. Use issue or return';
    END IF;
END //

DELIMITER ;
